(async()=>{if(new URLSearchParams(location.search).get('profile')!=='slope-pickup-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,D=SurvivalData;document.getElementById('welcome').hidden=true;const panel=document.createElement('div');panel.style='position:fixed;inset:0;overflow:auto;background:#fff;color:#234;z-index:10000';document.body.append(panel);const pre=document.createElement('pre');pre.id='report';panel.append(pre);let report={};const check=(k,v)=>{report[k]=v;pre.textContent=JSON.stringify(report,null,2);if(!v)throw Error(k);};await wait(2000);
for(const n of[0,4,16]){const c=W.caves[n],p=W.cavePoint(c,0,-14);q.apply({...D.fresh(),...p,y:W.ground(p.x,p.z),yaw:Math.atan2(-c.fx,-c.fz),pitch:0,worldTime:360,automaticTime:false,weatherMode:'clear'});q.setPlaying(true);await wait(400);q.camera.lookAt(c.x,c.y+2,c.z);q.renderer.render(q.scene,q.camera);const img=document.createElement('img');img.id='entrance-'+n;img.style='width:100%';img.src=q.renderer.domElement.toDataURL();panel.append(img);}
const r=q.world.resources.find(r=>r.kind==='ore'&&r.source.type==='cave-wall')||q.world.resources.find(r=>r.kind==='ore');for(const action of ['attack','interact']){q.apply({...D.fresh(),x:r.x+1,z:r.z,y:r.y,yaw:Math.PI,pitch:1.2,hand:'pickaxe',quickSlots:['pickaxe',null,null,null,null],activeSlot:0,inventory:{pickaxe:1},worldTime:360,automaticTime:false});q.setPlaying(true);q[action]();check(action+'ProximityPickup',(q.state.inventory.ore||0)>0);}check('done',true);document.title='斜面・入口・採取の確認完了';})().catch(e=>{document.getElementById('report').textContent+='\n'+e.stack;document.title='QA error';});
